#!/usr/bin/env python3
"""
ticker_lookup.py — find and check stocks for the widget's + form. Prints
one JSON object. Needs yfinance (widget_command.sh picks the right Python).

    python3 ticker_lookup.py search "shopify"    # matches by name or ticker
    python3 ticker_lookup.py quote SHOP.TO       # name, price, currency, ...
    python3 ticker_lookup.py look SHOP.TO        # + price history for charts
    python3 ticker_lookup.py news SHOP.TO        # 3 latest headlines (only
                                                 # with _settings.news true)

Anything Yahoo Finance lists works: US and foreign stocks (SHOP.TO, VOD.L,
7203.T, M&M.NS), ETFs, funds, crypto (BTC-USD), futures (GC=F).
"""

import argparse
import json
import math
import os
import sys

from portfolio_file import TICKER_RE, held_shares
from portfolio_tracker import (SPARK_DAYS, compute_changes, date_to_close_epoch,
                               fetch_one, infer_currency, load_settings,
                               news_for, now_epoch, resolve_currency, rnd,
                               split_currency, volatility)

SEARCH_TYPES = {"EQUITY", "ETF", "MUTUALFUND", "CRYPTOCURRENCY", "INDEX",
                "FUTURE", "CURRENCY"}


def out(obj):
    print(json.dumps(obj, allow_nan=False))


def read_json(path):
    try:
        with open(path) as f:
            return json.load(f)
    except Exception:
        return None


def holdings(positions_path):
    raw = read_json(positions_path) or {}
    return {k: held_shares(v) for k, v in raw.items()
            if not k.startswith("_") and held_shares(v)}


def watched(positions_path):
    raw = read_json(positions_path) or {}
    return [str(w).upper() for w in raw.get("_watch") or [] if isinstance(w, str)]


def cache_path(positions_path, name):
    return os.path.join(os.path.dirname(os.path.abspath(positions_path)),
                        ".cache", name)


def display_rate(cur, positions_path, yf):
    """(display currency, value of one unit of `cur` in it or None)."""
    cache = read_json(cache_path(positions_path, "data.json")) or {}
    display = cache.get("currency")
    if not display:
        display = resolve_currency(load_settings(read_json(positions_path) or {})["currency"])
    iso, mult = split_currency(cur)
    rate = 1.0 if iso == display else (cache.get("fxRates") or {}).get(iso)
    if rate is None:
        try:
            rate = last_close(yf.Ticker("%s%s=X" % (iso, display)).history(
                period="5d", interval="1d", auto_adjust=False))
        except Exception:
            rate = None
    return display, (round(rate * mult, 8) if rate else None)


def search(query, positions_path, yf):
    held = holdings(positions_path)
    try:
        found = yf.Search(query, max_results=10, news_count=0, timeout=10).quotes
    except Exception as e:
        return {"query": query, "results": [], "error": "search failed: %s" % e}
    results = []
    for q in found or []:
        sym = (q.get("symbol") or "").upper()
        if not sym or not TICKER_RE.match(sym):
            continue
        if q.get("quoteType") and q["quoteType"] not in SEARCH_TYPES:
            continue
        results.append({
            "symbol": sym,
            "name": (q.get("longname") or q.get("shortname") or "").strip(),
            "exchange": q.get("exchDisp") or q.get("exchange") or "",
            "type": q.get("typeDisp") or q.get("quoteType") or "",
            "held": held.get(sym),
        })
    return {"query": query, "results": results[:6]}


def last_close(frame):
    for _, row in frame.iloc[::-1].iterrows():
        c = row.get("Close")
        if c is not None and not (isinstance(c, float) and math.isnan(c)):
            return float(c)
    return None


def quote(symbol, positions_path, yf):
    """Name, price and currency of one symbol, plus displayRate: what one
    unit of its quote currency is worth in the widget's display currency
    (so the form can turn "$1000" into a share count)."""
    t = yf.Ticker(symbol)
    try:
        frame = t.history(period="5d", interval="1d", auto_adjust=False)
    except Exception as e:
        return {"symbol": symbol, "error": "lookup failed: %s" % e}
    price = last_close(frame) if frame is not None and not frame.empty else None
    if price is None:
        return {"symbol": symbol,
                "error": "Yahoo has no prices for %s — try searching by name" % symbol}
    try:
        md = t.history_metadata or {}
    except Exception:      # raises for some symbols with sparse metadata
        md = {}
    live = md.get("regularMarketPrice")
    if isinstance(live, (int, float)) and math.isfinite(live) and live > 0:
        price = float(live)
    cur = md.get("currency") or infer_currency(symbol)
    display, rate = display_rate(cur, positions_path, yf)

    return {
        "symbol": symbol,
        "name": md.get("longName") or md.get("shortName") or "",
        "exchange": md.get("fullExchangeName") or md.get("exchangeName") or "",
        "type": md.get("instrumentType") or "",
        "currency": cur,
        "price": round(price, 6),
        "displayCurrency": display,
        "displayRate": rate,
        "held": holdings(positions_path).get(symbol),
    }


def look(symbol, positions_path, yf):
    """Everything the widget's detail view shows for one ticker — held,
    watched or just looked up: price, changes, volatility score and full-
    resolution series for the 1D/1W/1M/3M/1Y chart tabs. Daily/hourly bars
    come from the widget's bars cache when it has them (one request instead
    of three)."""
    bars = (read_json(cache_path(positions_path, "bars.json")) or {}).get(symbol)
    try:
        r = fetch_one(symbol, yf, bars, want_currency=True)
    except Exception:
        return {"symbol": symbol,
                "error": "Yahoo has no prices for %s — try searching by name" % symbol}
    price = r["price"]
    prev_close = r.get("prevClose") or price
    day_pct = (price / prev_close - 1) * 100 if prev_close else None
    vol, score = volatility([c for _, c in r["daily"]])
    meta = (read_json(cache_path(positions_path, "ticker_meta.json")) or {}).get(symbol) or {}
    try:
        md = yf.Ticker(symbol).history_metadata or {}
    except Exception:
        md = {}
    cur = r.get("currency") or md.get("currency") or meta.get("currency") or infer_currency(symbol)
    display, rate = display_rate(cur, positions_path, yf)
    week_ago = now_epoch() - 7 * 86400
    daily_pts = [[date_to_close_epoch(d), rnd(c)] for d, c in r["daily"]]
    return {
        "symbol": symbol,
        "name": md.get("longName") or md.get("shortName") or meta.get("name") or "",
        "exchange": md.get("fullExchangeName") or md.get("exchangeName") or "",
        "currency": cur, "displayCurrency": display, "displayRate": rate,
        "price": rnd(price), "prevClose": rnd(prev_close),
        "dayChangePct": rnd(day_pct), "dayChange": rnd(price - prev_close),
        "changes": compute_changes(r, price, day_pct),
        "volPct": rnd(vol, 1), "volScore": score,
        "earningsDate": meta.get("earnings"),
        "dividendRate": meta.get("dividendRate"),
        "spark": [rnd(c) for _, c in r["daily"]][-SPARK_DAYS:],
        "series": {                       # [[epoch, close], ...] at full resolution
            "1D": [[t, rnd(c)] for t, c in r["intraday"]],
            "1W": [[t, rnd(c)] for t, c in r["hourly"] if t >= week_ago],
            "1M": [[t, rnd(c)] for t, c in r["hourly"]],
            "3M": daily_pts[-63:],
            "1Y": daily_pts[-252:],       # the bars cache can reach further back
        },
        "held": holdings(positions_path).get(symbol),
        "watched": symbol in watched(positions_path),
        "stale": bool(r.get("stale")),
    }


def news_enabled(positions_path):
    """_settings.news is exactly true (anything else = off)."""
    raw = read_json(positions_path)
    s = raw.get("_settings") if isinstance(raw, dict) else None
    return isinstance(s, dict) and s.get("news") is True


def news(symbol, positions_path, yf):
    """The latest headlines of one ticker (news.json, fetched again after
    30 min): {ticker, on, items [{title, source, time, url}], t, cached,
    error null | "no headlines right now" | "news unavailable"}."""
    items, t, cached, failed = news_for(
        symbol, yf, os.path.dirname(cache_path(positions_path, "news.json")))
    return {"ticker": symbol, "on": True, "items": items, "t": t, "cached": cached,
            "error": "news unavailable" if failed
            else None if items else "no headlines right now"}


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    ap = argparse.ArgumentParser()
    ap.add_argument("action", choices=["search", "quote", "look", "news"])
    ap.add_argument("text")
    ap.add_argument("--positions", default=os.path.join(here, "positions.json"))
    args = ap.parse_args()
    if args.action == "news":
        # settings first: with news off, no yfinance import and no request
        sym = args.text.upper().strip()
        if not TICKER_RE.match(sym):
            out({"ticker": sym[:40], "error": "that doesn't look like a ticker"})
            return
        if not news_enabled(args.positions):
            out({"ticker": sym, "on": False, "items": []})
            return
    try:
        import yfinance as yf
    except ImportError:
        out({"error": "yfinance isn't installed — run install.sh (see README)"})
        return
    if args.action == "search":
        query = " ".join(args.text.split())[:60]
        out(search(query, args.positions, yf) if len(query) >= 1
            else {"query": query, "results": []})
    else:
        sym = args.text.upper().strip()
        if not TICKER_RE.match(sym):
            out({"symbol": sym, "error": "that doesn't look like a ticker — try searching by name"})
            return
        out(quote(sym, args.positions, yf) if args.action == "quote"
            else news(sym, args.positions, yf) if args.action == "news"
            else look(sym, args.positions, yf))


if __name__ == "__main__":
    main()

files.web_main.py:
"""
web_main.py - what widget_command.sh does on the Mac, for the Portfolio web
app (Pyodide in a Web Worker). The widget's own Python files are unchanged;
this module only fits them to the browser:

  * threads run one after another (Pyodide has none), subprocess answers the
    "defaults read -g AppleLocale" question with the browser's locale
  * yfinance is web_yf (Yahoo data through the site's /api/yf function)
  * positions.json and .cache live in /pw, which the worker keeps in the
    browser's IndexedDB; the scripts live in /app

The worker calls: setup(cfg), tick(fetch_running, hist_running), refresh(),
history(), helper(args). Each returns a JSON string.
"""
import concurrent.futures as cf
import contextlib
import io
import json
import os
import re
import shutil
import subprocess
import sys
import threading
import time
import zipfile

APP, DATA = "/app", "/pw"
POS = DATA + "/positions.json"
CACHE = DATA + "/.cache"
F = {n: CACHE + "/" + f for n, f in dict(
    data="data.json", progress="progress.json", log="fetch.log", failed="fetch.failed",
    request="refresh.request", refresh_after="refresh_after", hist_needed="history.needed",
    hist_progress="history_progress.json", hist_failed="history.failed", hist_done="history.done",
    hist_log="history.log", update="update_release.json").items()}

MAX_CACHE_AGE, RETRY_AFTER, MAX_RETRY_AFTER, RATE_LIMIT_WAIT = 270, 120, 1800, 900
HISTORY_RETRY_AFTER, HISTORY_REPEAT_AFTER, HISTORY_MIN_CACHE_AGE = 1800, 600, 120

CFG = {"locale": "en_US", "version": "13.6"}
download = None        # (filename, bytes) for the page to save, after export
_post = None           # worker message hook


# ---------------------------------------------------------------- shims
class _SyncExecutor(object):
    """ThreadPoolExecutor stand-in: each job runs when it is submitted."""
    def __init__(self, max_workers=None, *a, **k):
        pass

    def submit(self, fn, *args, **kwargs):
        f = cf.Future()
        try:
            f.set_result(fn(*args, **kwargs))
        except BaseException as e:   # noqa: B902 - the future carries it
            f.set_exception(e)
        return f

    def map(self, fn, *its, **k):
        return [fn(*a) for a in zip(*its)]

    def shutdown(self, wait=True, cancel_futures=False):
        pass

    def __enter__(self):
        return self

    def __exit__(self, *a):
        return False


class _SyncThread(threading.Thread):
    """Thread stand-in: start() runs the target right away."""
    def start(self):
        self._pw_done = True
        try:
            self.run()
        except Exception:
            pass

    def join(self, timeout=None):
        return None

    def is_alive(self):
        return False


_real_run = subprocess.run


def _fake_run(cmd, *a, **k):
    if isinstance(cmd, (list, tuple)) and list(cmd[:4]) == ["defaults", "read", "-g", "AppleLocale"]:
        return subprocess.CompletedProcess(cmd, 0, stdout=CFG["locale"] + "\n", stderr="")
    raise OSError("not available in the browser")


def _install_shims():
    cf.ThreadPoolExecutor = _SyncExecutor
    threading.Thread = _SyncThread
    subprocess.run = _fake_run
    subprocess.Popen = lambda *a, **k: (_ for _ in ()).throw(OSError("not available in the browser"))
    import web_yf
    sys.modules["yfinance"] = web_yf


# ---------------------------------------------------------------- helpers
def _age(path):
    try:
        if os.path.getsize(path) > 0:
            return max(0, int(time.time() - os.path.getmtime(path)))
    except OSError:
        pass
    return 999999


def _read(path, limit=None):
    try:
        with open(path, encoding="utf-8") as f:
            return f.read() if limit is None else f.read()[-limit:]
    except Exception:
        return ""


def _write(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(text)
    os.replace(tmp, path)


def _rm(*paths):
    for p in paths:
        try:
            os.remove(p)
        except OSError:
            pass


def _stamp_fail():
    parts = _read(F["failed"]).split()
    n = int(parts[1]) if len(parts) > 1 and parts[1].isdigit() else 0
    _write(F["failed"], "%d %d\n" % (int(time.time()), n + 1))


def _mod(name):
    if name in sys.modules:
        return sys.modules[name]
    __import__(name)
    return sys.modules[name]


def _call(name, argv, stderr_too=False):
    """Run one of the widget's scripts like `python3 name.py argv...`:
    -> (exit code, stdout[, + stderr])."""
    mod = _mod(name)
    out, err = io.StringIO(), io.StringIO()
    old = sys.argv
    sys.argv = [name + ".py"] + list(argv)
    rc = 0
    try:
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(out if stderr_too else err):
            try:
                if name == "portfolio_tracker":
                    import web_yf
                    r = mod.main(list(argv), yf_module=web_yf)
                else:
                    r = mod.main()
                rc = r if isinstance(r, int) else 0
            except SystemExit as e:
                rc = e.code if isinstance(e.code, int) else (0 if e.code is None else 1)
                if e.code not in (None, 0) and not isinstance(e.code, int):
                    print(e.code, file=sys.stderr)
            except Exception as e:
                rc = 1
                print("error: %s" % e, file=sys.stderr)
    finally:
        sys.argv = old
    return rc, out.getvalue(), err.getvalue()


def _post_progress(kind, path):
    if _post:
        txt = _read(path)
        if txt.strip().startswith("{"):
            _post(json.dumps({"progress": kind, "value": json.loads(txt)}))


# ---------------------------------------------------------------- the worker's calls
def setup(cfg_json):
    CFG.update(json.loads(cfg_json))
    sys.path.insert(0, APP)
    if CFG.get("api"):
        import web_yf
        web_yf.API_URL = str(CFG["api"])
    os.environ["PORTFOLIO_HISTORY_GAP"] = "0"           # no pacing between symbols
    os.environ["PORTFOLIO_EXPORT_DIR"] = "/tmp/export"
    os.environ["PORTFOLIO_UPDATE_URL"] = "file://" + F["update"]
    os.environ["HOME"] = "/home/pyodide"
    _install_shims()
    os.makedirs(CACHE, exist_ok=True)
    # the "newest release" the update check sees: this version (the web app
    # is always current)
    _write(F["update"], json.dumps({"tag_name": "v" + CFG["version"], "name": CFG["version"],
                                    "html_url": "https://github.com/onnipackalen/uebersicht-portfolio/releases/latest",
                                    "assets": []}))
    first = not os.path.exists(POS)
    if first:
        shutil.copy(APP + "/positions.example.json", POS)
    return json.dumps({"ok": True, "first": first})


def _plan_signature():
    txt = _read(F["hist_needed"])
    pairs = re.findall(r'"start": "[^"]*"|"symbol": "[^"]*", "mode": "[^"]*"', txt)
    return "plan " + " ".join(sorted(pairs)) + (" " if pairs else "")


def tick(fetch_running, hist_running):
    """widget_command.sh's main path: what to start, and the envelope."""
    age = _age(F["data"])
    fail_age = _age(F["failed"])
    fail_wait = RETRY_AFTER
    parts = _read(F["failed"]).split()
    if parts:
        n = int(parts[1]) if len(parts) > 1 and parts[1].isdigit() else 1
        while n > 1 and fail_wait < MAX_RETRY_AFTER:
            fail_wait *= 2
            n -= 1
        fail_wait = min(fail_wait, MAX_RETRY_AFTER)
        if fail_wait < RATE_LIMIT_WAIT and re.search(r"too many requests|rate.?limit", _read(F["log"]), re.I):
            fail_wait = RATE_LIMIT_WAIT
    max_age = MAX_CACHE_AGE
    ra = _read(F["refresh_after"]).strip()
    if re.match(r"^\d{2,4}$", ra) and 60 <= int(ra) <= 3600:
        max_age = int(ra)
    hist_min_age = min(HISTORY_MIN_CACHE_AGE, max_age // 2)
    want_fetch = (age >= max_age and fail_age >= fail_wait) or os.path.exists(F["request"])
    start_fetch = want_fetch and not fetch_running
    if start_fetch:
        _rm(F["request"])
    running = fetch_running or start_fetch
    start_hist = (not hist_running and not running and _age(F["hist_needed"]) < 999999
                  and _age(F["data"]) < 999999 and not os.path.exists(F["failed"]) and age >= hist_min_age
                  and _age(F["hist_failed"]) >= HISTORY_RETRY_AFTER
                  and (_age(F["hist_done"]) >= HISTORY_REPEAT_AFTER
                       or _plan_signature() != _read(F["hist_done"]).rstrip("\n")))
    data = _read(F["data"]).strip() or None
    last_failed = os.path.exists(F["failed"])
    status = "loading" if running else "ready"
    if data is None and not running:
        status = "error"
    error_text = None
    if status == "error" or last_failed:
        error_text = _read(F["log"], 600) or None
    return json.dumps({"startFetch": start_fetch, "startHistory": start_hist,
                       "envelope": {"status": status, "cacheAgeSeconds": age, "lastFetchFailed": last_failed,
                                    "progress": None, "historyProgress": None, "updateResult": None,
                                    "errorText": error_text},
                       "data": data})


ASKED_FILE = CACHE + "/web_requests.json"   # what the last refresh asked for


def _prefetch_refresh():
    """One batch for what a refresh will ask: exactly what the last refresh
    asked for (same symbols), plus a guess for symbols it didn't have: the day
    of 5-minute bars, a year of daily closes, a month of hourly ones, and the
    search entry (name, sector)."""
    import web_yf
    try:
        pos = json.load(open(POS))
    except Exception:
        return
    syms = [k for k in pos if not k.startswith("_")] + [s for s in pos.get("_watch") or [] if isinstance(s, str)]
    try:
        last = json.load(open(ASKED_FILE))
    except Exception:   # never refreshed here: what a refresh of the demo asks
        try:
            last = json.load(open(APP + "/demo_requests.json"))
        except Exception:
            last = []
    reqs = [p for p in last if isinstance(p, dict)]
    known = {str(p.get("s") or p.get("q") or "").upper() for p in reqs}
    for s in syms:
        if s.upper() in known:
            continue
        reqs.append(web_yf.chart_request(s, "1d", "5m", prepost=True))
        reqs.append(web_yf.chart_request(s, "1y", "1d"))
        reqs.append(web_yf.chart_request(s, "1mo", "1h"))
        reqs.append(web_yf.chart_request(s, "2y", "1d"))     # dividends
        reqs.append(web_yf.search_request(s, 6))
    # date-bound requests (p1/p2) move with time: only ranges are reused
    web_yf.prefetch([p for p in reqs if "p1" not in p])


def _remember_requests():
    import web_yf
    seen, keep = set(), []
    for p in web_yf.ASKED:
        k = json.dumps(p, sort_keys=True)
        if k not in seen and "p1" not in p:
            seen.add(k)
            keep.append(p)
    try:
        _write(ASKED_FILE, json.dumps(keep[:400]))
    except Exception:
        pass


def refresh():
    import web_yf
    web_yf.clear()
    web_yf.on_request = lambda: _post_progress("fetch", F["progress"])
    _prefetch_refresh()
    t0 = time.time()
    rc, out, err = _call("portfolio_tracker", ["--json", "--positions", POS, "--progress-file", F["progress"]])
    _write(F["log"], err)
    if rc in (0, 3):
        _remember_requests()
    _write(CACHE + "/web_timing.json", json.dumps({"seconds": round(time.time() - t0, 2), "net": web_yf.NET[0],
                                                   "asked": len(web_yf.ASKED)}))
    ok = False
    if rc in (0, 3) and out.strip():
        try:
            json.loads(out)
            _write(F["data"], out)
            ok = True
        except ValueError:
            pass
    if ok and rc == 0:
        _rm(F["failed"])
    else:
        _stamp_fail()
    _call("portfolio_tracker", ["--daily-backup", "--positions", POS])
    _rm(F["progress"])
    web_yf.on_request = None
    return json.dumps({"ok": ok, "rc": rc})


def history():
    import web_yf
    sig = _plan_signature()
    web_yf.on_request = lambda: _post_progress("history", F["hist_progress"])
    rc, out, err = _call("portfolio_tracker", ["--fetch-history", "--positions", POS,
                                               "--progress-file", F["hist_progress"]])
    _write(F["hist_log"], err)
    if rc == 0:
        _rm(F["hist_failed"])
        _write(F["hist_done"], sig + "\n")
    else:
        _write(F["hist_failed"], "%d\n" % int(time.time()))
    _rm(F["hist_progress"])
    web_yf.on_request = None
    return json.dumps({"ok": rc == 0, "rc": rc})


def _reply(out, fallback):
    out = (out or "").strip()
    return out if out else json.dumps(fallback)


def _export():
    global download
    shutil.rmtree("/tmp/export", ignore_errors=True)
    rc, out, err = _call("export", ["--positions", POS])
    files = []
    for root, _, names in os.walk("/tmp/export"):
        for n in names:
            files.append(os.path.join(root, n))
    if files:
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
            for p in sorted(files):
                z.write(p, os.path.relpath(p, "/tmp/export"))
        download = ("Portfolio-export-%s.zip" % time.strftime("%Y-%m-%d"), buf.getvalue())
        try:   # the widget says "exported to <dirShown>": name the download instead
            r = json.loads(out)
            if r.get("ok"):
                r["dirShown"] = download[0] + " (your downloads)"
                out = json.dumps(r)
        except ValueError:
            pass
    return _reply(out, {"error": "export failed"})


def helper(args_json):
    """widget_command.sh ARGS... -> its stdout."""
    a = json.loads(args_json)
    c = a[0] if a else ""
    if c in ("search", "quote", "look"):
        rc, out, _ = _call("ticker_lookup", [c, a[1] if len(a) > 1 else "", "--positions", POS])
        return _reply(out, {"error": "lookup failed — Yahoo may be busy, try again in a minute"})
    if c in ("buy", "sell", "watch", "unwatch"):
        name, rest = {"buy": ("add_position", a[1:]), "sell": ("remove_position", a[1:]),
                      "watch": ("watchlist", ["add"] + a[1:]), "unwatch": ("watchlist", ["remove"] + a[1:])}[c]
        rc, out, _ = _call(name, ["--positions", POS] + rest, stderr_too=True)
        return out
    if c == "setting":
        rc, out, _ = _call("set_setting", ["--positions", POS, "--"] + a[1:3])
        return _reply(out, {"error": "could not save the setting"})
    if c == "export":
        return _export()
    if c == "alert":
        rc, out, _ = _call("alerts", ["--json", "--positions", POS, "--"] + a[1:])
        return _reply(out, {"error": "could not save the alert"})
    if c == "meta":
        rc, out, _ = _call("holding_meta", ["--json", "--positions", POS, "--"] + a[1:])
        return _reply(out, {"error": "could not save the note"})
    if c == "news":
        rc, out, _ = _call("ticker_lookup", ["news", "--positions", POS, "--", a[1] if len(a) > 1 else ""])
        return _reply(out, {"error": "news unavailable"})
    if c == "days":
        rc, out, _ = _call("portfolio_tracker", ["--positions", POS, "--days-before", a[1] if len(a) > 1 else "",
                                                 "--days-count", a[2] if len(a) > 2 and a[2] else "400"])
        return _reply(out, {"rows": [], "first": None, "total": 0, "error": True})
    if c == "import":
        sub = a[1] if len(a) > 1 else ""
        if sub in ("preview", "commit"):
            rc, out, _ = _call("import_positions", ["--positions", POS] + (["--commit"] if sub == "commit" else []) + a[2:])
            return _reply(out, {"error": "the import failed"})
        return json.dumps({"error": "import takes preview, commit or choose"})
    if c == "update":
        if len(a) > 1 and a[1] == "check":
            rc, out, _ = _call("portfolio_tracker", ["--positions", POS, "--check-update"])
            return _reply(out, {"error": "the check failed"})
        return json.dumps({"ok": False, "message": "the web app is always the newest version"})
    if c == "setup":
        if len(a) > 1 and a[1] == "check":
            _write(F["request"], "")
        return json.dumps({"ok": True})
    return json.dumps({"error": "unknown command"})


def take_download():
    """The file an export made, for the page to save: (name, bytes) or None."""
    global download
    d, download = download, None
    return d


def debug():
    """For testing from the page (PW_DEBUG()): logs and request counts, no holdings."""
    import web_yf
    calls = {}
    for c in web_yf.CALLS:
        calls[c[0]] = calls.get(c[0], 0) + 1
    return json.dumps({"timing": _read(CACHE + "/web_timing.json"), "asked": _read(ASKED_FILE),
                       "fetchLog": _read(F["log"], 1500), "historyLog": _read(F["hist_log"], 1500),
                       "failed": _read(F["failed"]), "calls": calls, "cached": len(web_yf._cache),
                       "files": sorted(os.listdir(CACHE)) if os.path.isdir(CACHE) else []})

files.web_yf.py:
"""
web_yf.py - a yfinance stand-in for the Portfolio web app (runs in Pyodide).

The widget's Python never needs pandas: its tests swap yfinance for a small
fake (tools/tests/fake_yf.py) and this module offers the same interface,
backed by real Yahoo data from the site's /api/yf function:

    Ticker(sym).history(period|start/end, interval, prepost)  -> Frame of Close
    Ticker(sym).history_metadata                              -> chart "meta"
    Ticker(sym).info        -> sector / quoteType / names (from Yahoo search)
    Ticker(sym).get_dividends(period) -> Series of (datetime, amount)
    Ticker(sym).news / get_news()     -> headlines (Yahoo search news)
    Ticker(sym).calendar    -> {}  (earnings dates need a Yahoo sign-in token)
    Ticker(sym).options     -> []  (same)
    Search(q).quotes

Requests are synchronous XMLHttpRequests (fine inside a Web Worker) and
answers are kept in memory for this session; prefetch() asks for many at once.
"""
import json
import time
from datetime import datetime, timezone
from zoneinfo import ZoneInfo

try:
    import js   # Pyodide
except ImportError:   # pragma: no cover
    js = None

API = "/api/yf"
API_URL = None      # full address of the price feed when it is on another site (set by web_main)
CALLS = []          # (kind, symbol, ...) - what was asked, for tuning prefetch
ASKED = []          # every /api/yf request dict this run asked for (cache hits too)
NET = [0]           # network round trips this run
_cache = {}         # request key -> parsed body
_tz_cache = {}
on_request = None   # set by web_main: called after every network round trip


class YahooError(RuntimeError):
    pass


def _key(p):
    return json.dumps(p, sort_keys=True, separators=(",", ":"))


def _xhr(method, url, body=None):
    x = js.XMLHttpRequest.new()
    x.open(method, url, False)
    if body is not None:
        x.setRequestHeader("Content-Type", "text/plain;charset=UTF-8")
        x.send(body)
    else:
        x.send()
    return int(x.status), str(x.responseText or "")


def _api():
    return API_URL or (str(js.location.origin) + API)


def _get(p):
    k = _key(p)
    ASKED.append(p)
    if k in _cache:
        return _cache[k]
    qs = "&".join("%s=%s" % (a, js.encodeURIComponent(str(b))) for a, b in sorted(p.items()))
    NET[0] += 1
    status, text = _xhr("GET", _api() + "?" + qs)
    if on_request:
        on_request()
    try:
        body = json.loads(text)
    except ValueError:
        raise YahooError("price feed answered %s" % status)
    if status == 429 or (status >= 500 and "429" in text):
        raise YahooError("Too Many Requests")
    if status != 200:
        msg = (body.get("error") if isinstance(body, dict) else None) or ("price feed answered %s" % status)
        if isinstance(body, dict) and isinstance(body.get("chart"), dict) and body["chart"].get("error"):
            msg = (body["chart"]["error"] or {}).get("description") or msg
        raise YahooError(str(msg))
    _cache[k] = body
    return body


def prefetch(requests):
    """Ask for many requests in one round trip (the function runs them in
    parallel); answers land in the cache. Never raises."""
    todo = [p for p in requests if _key(p) not in _cache]
    for i in range(0, len(todo), 50):
        part = todo[i:i + 50]
        try:
            NET[0] += 1
            status, text = _xhr("POST", _api() + "?k=batch", json.dumps(part))
            if on_request:
                on_request()
            if status != 200:
                continue
            for p, r in zip(part, json.loads(text)):
                if isinstance(r, dict) and r.get("status") == 200:
                    _cache[_key(p)] = r.get("body")
        except Exception:
            pass


def clear():
    _cache.clear()
    del ASKED[:]
    NET[0] = 0


# ---------------------------------------------------------------- frames
class Frame(object):
    def __init__(self, rows):
        self.rows = rows

    @property
    def empty(self):
        return not self.rows

    def iterrows(self):
        for ts, c in self.rows:
            yield ts, {"Close": c}

    @property
    def iloc(self):
        return _ILoc(self)

    def __len__(self):
        return len(self.rows)


class _ILoc(object):
    def __init__(self, frame):
        self.frame = frame

    def __getitem__(self, k):
        if isinstance(k, slice):
            return Frame(self.frame.rows[k])
        ts, c = self.frame.rows[k]
        return {"Close": c}


class Series(object):
    def __init__(self, rows):
        self.rows = rows

    def items(self):
        return iter(self.rows)

    def __len__(self):
        return len(self.rows)


def _zone(name):
    if not name:
        return timezone.utc
    z = _tz_cache.get(name)
    if z is None:
        try:
            z = ZoneInfo(name)
        except Exception:
            z = timezone.utc
        _tz_cache[name] = z
    return z


DAILY = ("1d", "5d", "1wk", "1mo", "3mo")
PERIODS = {"1d", "5d", "1mo", "3mo", "6mo", "1y", "2y", "5y", "10y", "ytd", "max"}


def _epoch(day):
    return int(datetime.strptime(day, "%Y-%m-%d").replace(tzinfo=timezone.utc).timestamp())


def chart_request(symbol, period=None, interval="1d", start=None, end=None, prepost=False):
    """The /api/yf request a history() call makes (also used by prefetch)."""
    p = {"k": "chart", "s": symbol, "interval": "60m" if interval == "1h" else interval}
    if start is not None:
        p["p1"] = str(_epoch(start) if isinstance(start, str) else int(start.timestamp()))
        if end is not None:
            p["p2"] = str(_epoch(end) if isinstance(end, str) else int(end.timestamp()))
    else:
        p["range"] = period if period in PERIODS else "1mo"
    if prepost and interval not in DAILY:
        p["prepost"] = "1"
    if interval in DAILY:
        p["events"] = "div"    # one answer serves history() and get_dividends()
    return p


def _result(body):
    try:
        res = body["chart"]["result"][0]
    except (KeyError, IndexError, TypeError):
        res = None
    if not res:
        raise YahooError("no data")
    return res


class Ticker(object):
    def __init__(self, symbol):
        self.symbol = str(symbol)
        self.history_metadata = {}
        self.options = []

    # -- prices
    def history(self, period=None, interval="1d", start=None, end=None,
                auto_adjust=False, prepost=False, **kw):
        CALLS.append(("history", self.symbol, period, interval, start, end, bool(prepost)))
        p = chart_request(self.symbol, period, interval, start, end, prepost)
        try:
            res = _result(_get(p))
        except YahooError as e:
            if str(e) == "no data" or "No data found" in str(e) or "delisted" in str(e):
                return Frame([])
            raise
        meta = res.get("meta") or {}
        self.history_metadata = meta
        tz = _zone(meta.get("exchangeTimezoneName"))
        stamps = res.get("timestamp") or []
        ind = res.get("indicators") or {}
        if auto_adjust and ind.get("adjclose"):
            closes = (ind["adjclose"][0] or {}).get("adjclose") or []
        else:
            closes = ((ind.get("quote") or [{}])[0] or {}).get("close") or []
        daily = interval in DAILY
        rows, seen = [], set()
        for t, c in zip(stamps, closes):
            if c is None or t is None:
                continue
            ts = datetime.fromtimestamp(t, tz)
            if daily:
                ts = datetime(ts.year, ts.month, ts.day, tzinfo=tz)
                if ts in seen:          # Yahoo can repeat today's bar
                    rows = [r for r in rows if r[0] != ts]
                seen.add(ts)
            rows.append((ts, float(c)))
        if start is not None and end is not None and daily:
            hi = datetime.strptime(end, "%Y-%m-%d").date() if isinstance(end, str) else end.date()
            rows = [r for r in rows if r[0].date() < hi]
        return Frame(rows)

    def get_dividends(self, period="max"):
        CALLS.append(("divs", self.symbol, period))
        p = chart_request(self.symbol, period if period in PERIODS else "max", "1d")
        try:
            res = _result(_get(p))
        except YahooError as e:
            if str(e) == "no data":
                return Series([])
            raise
        tz = _zone((res.get("meta") or {}).get("exchangeTimezoneName"))
        divs = ((res.get("events") or {}).get("dividends") or {}).values()
        rows = sorted((datetime.fromtimestamp(int(d["date"]), tz), float(d["amount"]))
                      for d in divs if d.get("date") is not None and d.get("amount") is not None)
        return Series(rows)

    # -- facts
    @property
    def info(self):
        CALLS.append(("info", self.symbol))
        q = _quote_for(self.symbol)
        meta = self.history_metadata or _cached_meta(self.symbol)
        if not meta and not q:
            try:
                meta = _result(_get(chart_request(self.symbol, "5d", "1d"))).get("meta") or {}
            except Exception:
                meta = {}
        qt = (q or {}).get("quoteType") or meta.get("instrumentType") or "EQUITY"
        return {
            "sector": (q or {}).get("sectorDisp") or (q or {}).get("sector"),
            "industry": (q or {}).get("industryDisp") or (q or {}).get("industry"),
            "quoteType": qt,
            "longName": (q or {}).get("longname") or meta.get("longName"),
            "shortName": (q or {}).get("shortname") or meta.get("shortName"),
            "currency": meta.get("currency"),
            "dividendRate": None,
        }

    @property
    def calendar(self):
        CALLS.append(("calendar", self.symbol))
        return {}

    def option_chain(self, exp=None):
        raise YahooError("options are not available in the web app")

    # -- news
    def _news(self, count=10):
        CALLS.append(("news", self.symbol))
        body = _get({"k": "search", "q": self.symbol, "n": "1", "news": str(max(1, min(20, count)))})
        out = []
        for n in body.get("news") or []:
            t = n.get("providerPublishTime")
            out.append({"id": n.get("uuid"), "content": {
                "title": n.get("title") or "",
                "pubDate": datetime.fromtimestamp(int(t), timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ") if t else "",
                "displayTime": "", "provider": {"displayName": n.get("publisher") or ""},
                "canonicalUrl": {"url": n.get("link") or ""}, "clickThroughUrl": {"url": n.get("link") or ""},
                "contentType": "STORY"}})
        return out

    @property
    def news(self):
        return self._news()

    def get_news(self, count=10, tab="news"):
        return self._news(count)[:count]


def _cached_meta(symbol):
    """The chart "meta" of any answer already here for this symbol."""
    for k, body in _cache.items():
        if '"k":"chart"' in k and ('"s":%s' % json.dumps(symbol)) in k:
            try:
                return _result(body).get("meta") or {}
            except Exception:
                continue
    return {}


def search_request(query, n=10):
    return {"k": "search", "q": str(query), "n": str(n)}


def _quote_for(symbol):
    """Yahoo search's entry for exactly this symbol (names, type, sector)."""
    try:
        body = _get(search_request(symbol, 6))
    except Exception:
        return None
    for q in body.get("quotes") or []:
        if str(q.get("symbol") or "").upper() == symbol.upper():
            return q
    return None


class Search(object):
    def __init__(self, query, max_results=8, news_count=0, **kw):
        CALLS.append(("search", query))
        body = _get(search_request(query, max(1, min(20, int(max_results or 8)))))
        self.quotes = body.get("quotes") or []
        self.news = []


def __getattr__(name):     # yf.set_tz_cache_location(...) and friends: no-ops
    if name.startswith("set_") or name in ("enable_debug_mode",):
        return lambda *a, **k: None
    raise AttributeError(name)
